-- =============================================================================
-- Arreglo en produccion de lo que quedo pendiente del volcado de fichas:
--   1. devolver el portal/escalera a las direcciones que lo perdieron
--   2. fusionar las comunidades duplicadas (una comunidad, varios encargos)
--   3. repartir cada nota a su encargo
--
-- Los UUID de local y produccion NO coinciden: todo se traduce por
-- migracion_monday.monday_item_id, que si es el mismo en los dos lados.
-- Idempotente.
-- =============================================================================

-- ---------- 1. direcciones ----------
create temp table _dir (monday_item_id text, direccion text);
update comunidades c set direccion = d.direccion
  from _dir d join migracion_monday m
    on m.tabla_destino='comunidades' and m.monday_item_id = d.monday_item_id
 where c.id = m.registro_id and c.direccion is distinct from d.direccion;

-- ---------- 2. fusiones ----------
-- En local la comunidad superviviente quedo con los DOS items de Monday. En
-- produccion esos dos items apuntan a dos filas distintas: se unifican en una.
-- Un grupo = los items de Monday que en LOCAL comparten comunidad. Puede tener
-- 2, 3 o 4 items (Hernan Cortes tiene 4 encargos). Se resuelve cada item a su
-- fila de produccion y, si el grupo cae en varias filas, se unifican.
create temp table _fus (grupo int, monday_item_id text);

create temp table _res as
select f.grupo, m.registro_id comunidad_id,
       (select count(*) from proyectos p where p.comunidad_id = m.registro_id) proyectos
  from _fus f join migracion_monday m
    on m.tabla_destino = 'comunidades' and m.monday_item_id = f.monday_item_id;

-- sobrevive la que mas proyectos tiene colgando; a igualdad, la de id menor
create temp table _merge as
select r.comunidad_id absorbida, s.sobrevive
  from _res r
  join (select grupo, (array_agg(comunidad_id order by proyectos desc, comunidad_id))[1] sobrevive
          from _res group by grupo having count(distinct comunidad_id) > 1) s
    on s.grupo = r.grupo
 where r.comunidad_id <> s.sobrevive;
update beneficiarios_reparto_caes x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update condicionantes_comunidad x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update destinatarios_informe x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update documentos x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update expedientes x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update hojas_encargo x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update interaccion_comunidad x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update migracion_ficha x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update observaciones_expediente x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update operaciones_caes x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update oportunidades x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update personas_comunidad x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update proyectos x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update resumenes_ia x set comunidad_id = mg.sobrevive from _merge mg where x.comunidad_id = mg.absorbida;
update migracion_monday x set registro_id = mg.sobrevive
  from _merge mg where x.tabla_destino='comunidades' and x.registro_id = mg.absorbida;
delete from comunidades c using _merge mg where c.id = mg.absorbida;

-- ---------- 3. reparto de notas a su encargo ----------
create temp table _nota (com_item text, proy_item text, texto text);
update observaciones_expediente o set proyecto_id = mp.registro_id
  from _nota n
  join migracion_monday mc on mc.tabla_destino='comunidades' and mc.monday_item_id = n.com_item
  join migracion_monday mp on mp.tabla_destino='proyectos'   and mp.monday_item_id = n.proy_item
 where o.comunidad_id = mc.registro_id and o.texto = n.texto
   and o.proyecto_id is distinct from mp.registro_id;
