insert into _nota values
('2987053359', '1771683221', 'Presidente David 635 85 47 45 . Es para ir a ver que ascensor les entra, ver la solucion. Es uno de los que te ha pasado Mª Angeles MAFER. El presidente, David llega de currar a las 7:30, a partir de esa hora le da igual a que hora llegues. Le he dicho que sobre las 8:15, pero si es antes o despues, tambien puede ser.24/05/22 2. BRUNETE 3. FUENLABRADALlamé a David pero justo se había marchado al gimnasio, así que lo vi por mi cuenta. Se puede instalar un ascensor de 4 personas con embarque simple. No sería accesible, pero cabría perfectamente una silla de ruedas. La obra es muy sencilla. Habría que cambiar la ubicación de los contadores a un armario homologado, y limar un poco el ancho de las escaleras para aumentar el hueco existente. Habría que modificar en el portal las escaleras de acceso en planta baja y bajar la puerta principal. Calculo una obra aproximada de 90.000 €, donde lo más caro será la modificación de contadores eléctricos.'),
('2987063767', '1771683221', 'Presidente David 635 85 47 45 . Es para ir a ver que ascensor les entra, ver la solucion. Es uno de los que te ha pasado Mª Angeles MAFER. El presidente, David llega de currar a las 7:30, a partir de esa hora le da igual a que hora llegues. Le he dicho que sobre las 8:15, pero si es antes o despues, tambien puede ser.24/05/22 2. BRUNETE 3. FUENLABRADALlamé a David pero justo se había marchado al gimnasio, así que lo vi por mi cuenta. Se puede instalar un ascensor de 4 personas con embarque simple. No sería accesible, pero cabría perfectamente una silla de ruedas. La obra es muy sencilla. Habría que cambiar la ubicación de los contadores a un armario homologado, y limar un poco el ancho de las escaleras para aumentar el hueco existente. Habría que modificar en el portal las escaleras de acceso en planta baja y bajar la puerta principal. Calculo una obra aproximada de 90.000 €, donde lo más caro será la modificación de contadores eléctricos.'),
