('2018602275', '2018607820', '17/04/2024 ESCANEADO DE ZONAS COMUNES Y COCINA Y VESTIBULO DE UNA ENTRADA. PREPARA MODELO 3D'),
('2018602275', '2018607820', '06/11/2024 PRESENTACION 3D Y DECIDEN NO HACER ASCENSOR'),
('2018602275', '2018607820', '12/06/2025 Cuidado, el 3D que está en datos no corresponde. No usarlo como base para hacer el proyecto.'),
